    bag_examples_v2_toast: "🎁 Nuevos ejemplos en tu bolso: ideas de regalo, una lista para el hotel y otra para el vuelo ✨",
    faq_a_bag_examples_list: "Un bolso nuevo trae ejemplos que puedes cambiar o eliminar como cualquier otra cosa: Casa (compras, recetas, comidas de la semana), Familia (pequeños momentos, una lista para la fiesta de cumpleaños, actividades y clases), Ideas (ideas para el fin de semana, ideas de regalo según la cercanía con la persona y qué hacer con el dinero ahorrado) y Viajes (lugares a los que quieres ir, equipaje para el viaje, equipaje para el hotel y una lista para el vuelo al extranjero). Un bolso que ya existía recibe una sola vez los más nuevos, en sus propios bolsillos.",
    faq_q_bag_examples_list: "¿Qué ejemplos vienen en Mi bolso?",
    faq_a_nm_me1_guide: "Sky, tu personaje en New Me, en su primera forma (Sky 1). La primera vez, justo después de unirte, se abre un portal de luz con destellos alrededor y Sky sale volando de él, explica en unos pocos toques lo que viene y luego se queda junto a cada pregunta: mientras se eligen las comidas, escribe contigo en su libro, y un toque en su consejo muestra otro. Al final, Sky lo celebra contigo y te lleva a un recorrido corto, y cuando el recorrido termina, todavía tiene un momentito más contigo. Si sales a mitad –de las preguntas o del recorrido–, la próxima vez Sky se alegra de verte y te pregunta si seguir desde el mismo punto.",
    faq_q_nm_me1_guide: "¿Quién te acompaña al entrar en New Me?",
    nm_m1_day_text: "Cada día, un ✓ en cada comida, y yo lo cuento todo por ti.",
