    nm_m1_joy_text: "Tu menú te espera, y el mundo mágico ya está despertando.",
    nm_m1_joy_title: "¡Yupi! Ya está todo listo",
    nm_m1_magic_text: "Y cada paso de verdad que das abre más lugares en el mundo mágico",
    nm_m1_menu_text: "Tú y yo vamos a crear un menú a tu medida: comida que te encanta, a las horas que mejor te vienen.",
