    room_genie_again_no: "Ahora no",
    room_genie_again_no_msg: "Entonces es momento de alcanzar las metas que ya te has propuesto. Cuando llegues a la siguiente, allí te estará esperando algo ✨",
    room_genie_again_q: "¿Otra vez por aquí? ✨ ¿Te gustaría cambiar algo más en tu vida?",
    room_genie_again_yes: "Sí",
    room_genie_bye: "Hasta pronto",
    room_genie_rest: "El espíritu del bosque está descansando ahora: vuelve mañana ✨",
    faq_a_shop_holidays: "En la Lista de Compras, toca el regalo: aparecen en orden las fiestas de tu país (el de Ajustes), con sus fechas, que se calculan solas cada año. Toca una fiesta para ver una lista ya hecha de lo que se suele comprar para ella; todo está seleccionado (salvo lo que ya está en tu lista), desmarca lo que no necesites y toca «Añadir a la lista». Dos semanas antes de una fiesta aparece una pequeña tarjeta arriba de la lista; ✕ la oculta hasta la próxima fiesta.",
    faq_q_shop_holidays: "¿Cómo funciona «Qué comprar para la fiesta»?",
    shop_hol_add: "Añadir a la lista ({n})",
    shop_hol_added: "Añadidos a la lista: {n}",
    shop_hol_btn: "Qué comprar para la fiesta",
    shop_hol_items_title: "{holiday} – ¿qué comprar?",
    shop_hol_not_now: "Ahora no",
    faq_a_shop_delivery: "En la Lista de Compras, toca el camión: elige qué viene en el pedido (todo está seleccionado), cuándo llega (hoy, mañana u otro día) y a qué hora (por la mañana, al mediodía, por la tarde u «Otro…» para tu propio horario). Esos productos pasan a una tarjeta «En camino» arriba de la lista, con el día y el horario. Cuando llega el día, aparece «¿Llegó el pedido?» en Mi Día (y la tarjeta muestra «¿Llegó?»). Si llegó todo, pasan a «Volver a comprar». Si falta algo, toca lo que no llegó y vuelve directo a la lista.",
    faq_a_shop_departments: "La lista se ordena sola por las secciones del supermercado – frutas y verduras, pan, lácteos y huevos, carne y pescado, despensa, congelados, bebidas, snacks, limpieza, higiene, bebé y mascotas –, así recorres los pasillos en orden. La sección se reconoce por el nombre del producto. Si un producto quedó en el lugar equivocado, tócalo y elige su sección, u «Otra…» para escribir la tuya.",
    faq_a_shop_share_qty: "Sí. Junto a cada producto, + añade uno más (×2, ×3…) y − quita uno. El botón de compartir arriba de la Lista de Compras envía toda la lista, bien ordenada por secciones, por WhatsApp, por correo o como copia.",
    faq_a_shop_two_buttons: "Los dos significan «comprado». ✕ es para algo que compras una sola vez: sale de la lista (y espera en el archivo 🗑️ por si fue un error). ↺ es para lo que compras una y otra vez: sale de la lista y espera en «Volver a comprar»; lo abre el pequeño botón ↺ junto a la papelera, al final de la lista, y un toque ahí devuelve un producto a la lista. En «Editar», dentro, puedes sacar un producto. Al añadir un producto, lo que ya compraste antes aparece como sugerencia, y si ya está en la lista, simplemente pasa a ×2 en lugar de ocupar otra línea.",
    faq_q_shop_delivery: "¿Cómo funciona «Hice un pedido a domicilio»?",
    faq_q_shop_departments: "¿Por qué mi lista de compras está dividida en secciones?",
