    nm_demo_title: "Así funciona un cambio",
    faq_a_new_me_challenge_journal: "Cuando termina un reto (grande, mini o el reto de la semana), en la celebración aparece el botón 📝 ¿Cómo fue?, que abre una página en el diario de retos: cómo te sentiste (cinco caras), qué ayudó, qué fue difícil y qué me llevo de esto. Nada es obligatorio, y también puede quedar para más tarde. El diario es un diamante en la mochila mágica: cada reto terminado con su fecha y lo que se escribió, el más reciente primero; toca uno para leerlo, editarlo o compartirlo (solo se comparte lo que hay en la página). Un reto terminado también recibe una medalla en los logros, en «Retos que he terminado». El diario de retos es independiente del diario habitual.",
    faq_q_new_me_challenge_journal: "¿Qué es el diario de retos?",
