    nm_chj_take: "¿Qué me llevo de esto?",
    nm_chj_title: "Diario de retos",
    nm_chj_write: "Escribir cómo fue",
    nm_swap_time: "Hora",
    faq_a_ai_reminder_in_text: "Sí: escríbelo junto con la tarea, por ejemplo «mañana a las 17:00 recoger el paquete, con un recordatorio una hora antes». El recordatorio se guarda en la propia tarea: una hora antes, media hora antes, el día anterior, etc., y «recuérdame» sin hora significa 10 minutos antes. Un recordatorio escrito en el texto tiene prioridad sobre el campo de recordatorio de la misma ventana.",
    faq_q_ai_reminder_in_text: "¿Puedo pedir al asistente de IA un recordatorio en la misma solicitud?",
    myday_meals_all_done: "Todas las comidas de hoy están marcadas 🍽️",
    nm_tour_week_text: "Un pequeño reto para la semana. ✓ cada día, y al final, una llave.",
    books_home_chip: "{title} · pág. {page}",
    books_home_of: "de {total}",
    books_home_off_toast: "El libro salió de la pantalla de inicio",
    books_home_on_toast: "El libro está en la pantalla de inicio 📖",
    books_home_pin: "En la pantalla de inicio",
    books_home_q: "¿En qué página estoy?",
    books_home_save: "Guardar",
    faq_a_books_home_chip: "Sí. En el Rincón de lectura, en la tarjeta de un libro que estás leyendo, toca 📌 En la pantalla de inicio. Debajo del saludo de la pantalla de inicio aparece un botoncito con el libro y la página: tócalo, escribe el nuevo número de página y guarda, y el progreso queda registrado (también en el Rincón de lectura). Al tocar 📌 otra vez se quita. Puede haber varios libros a la vez – un botón para cada uno – y es igual en todos los dispositivos.",
    faq_a_new_me_week_challenge: "Un pequeño reto de una semana, elegido por ti. En el pasillo hay una tarjeta grande: «¿En qué te gustaría trabajar esta semana?». Tócala, elige un área (conmigo, con los demás, aprender y crecer, calma, pequeños pasos valientes, casa y rutina) y un reto, y decide cuándo empieza. Los mismos retos también están en la pantalla de retos, en 🌱 Crecimiento personal. Cada día se marca ✓ en la tarjeta (un día libre a la semana), y cada semana que termina trae una llave nueva para el mundo secreto. «Leer 2 páginas al día» se marca solo con las páginas registradas en el Rincón de lectura. Cuando termina la semana, 📌 Mantenerlo como tarea diaria lo añade a Mi Rutina a la hora que elijas, con un ✓ cada día. Solo hay un reto de la semana a la vez; los retos grandes y los mini retos siguen en paralelo.",
    faq_a_room_genie: "En el porche frente al mar, un toque en la lámpara de Aladino hace salir al espíritu del bosque, y empieza una conversación: cuál es tu deseo (qué te gustaría cambiar en tu vida), cómo se sentirá cuando se cumpla, qué es difícil en el camino y cómo se puede convertir la situación de ahora en algo bueno. Después, más o menos cuánto tiempo llevará, un primer paso pequeño y dos más, y un «si… entonces…» para cuando se ponga difícil. Al final aparece todo el deseo paso a paso, y puede convertirse en una meta en Mis Metas (los pasos pasan a ser hitos del camino, con fecha según el tiempo elegido; allí se puede cambiar todo) o guardarse en el diario, y entonces el espíritu se despide. No se guarda nada si no se elige una de las dos opciones. A partir de la segunda visita, el espíritu pregunta primero si te gustaría cambiar algo más en tu vida: «sí» lleva a la misma conversación; «ahora no», a un recordatorio de alcanzar las metas ya fijadas. El espíritu sale una vez al día: después de guardar un deseo (o después de «Ahora no»), descansa hasta mañana. Las preguntas siguen un método conocido para convertir un deseo en un plan: deseo, resultado, obstáculo y plan.",
    faq_q_books_home_chip: "¿Puedo ver mi libro y la página en la pantalla de inicio?",
    faq_q_new_me_week_challenge: "¿Qué es el reto de la semana?",
