    faq_a_new_me_game: "En New Me, los botones del juego siempre se quedan en el mismo lugar: en el pasillo, en la habitación secreta y en todo el bosque; solo cambia la pintura del centro. Arriba: el día en el camino, las llaves, la racha y la energía de hoy (cuánto se ha comido del plan), y debajo, la siguiente misión: la siguiente comida a su hora (un toque la abre, con ✓ Ya lo comí). A un lado: todo el día, retos y mi camino, y junto a ellos el reto de la semana: sus 7 días y un ✓ para hoy. Abajo: la mochila mágica (todo en New Me: mapa del mundo, mi camino, lista de compras, logros, diario de retos, medidas, fotos de progreso, calendario mensual, tabla diaria, recordatorios, menú en PDF y ajustes; se abre como una pantalla propia). El mapa del mundo, lo primero de la mochila, muestra todos los lugares del bosque: toca un lugar para ir allí; en un lugar cerrado se ve cuántas llaves necesita. Sky es tu personaje en el sendero del bosque: empieza como Sky 1, después de algunos retos (4 llaves) crece y se convierte en Sky 2, y cerca del final (9 llaves) en Sky 3, con una transformación que se ve en directo. Toca a Sky para ver todas las etapas: cualquier etapa ya alcanzada se puede elegir de nuevo, así que una anterior puede volver. Sky flota: se arrastra con el dedo o el ratón, y la entrada que toca se abre (una bloqueada muestra cuántas llaves faltan). Sky también te acompaña a cada habitación y lugar, y flota donde lo dejes: arrástralo a cualquier parte, y arrastra el anillo brillante que tiene debajo para girarlo por completo; mira hacia donde se mueve (en el ordenador: las flechas lo mueven, Q y E lo giran). En el pasillo, el pequeño 🏠 bajo la barra superior vuelve a la pantalla de inicio; en cada habitación y lugar, el botón de la misma esquina vuelve al pasillo.",
    faq_q_new_me_game: "¿Cómo funcionan los botones del juego, el mapa del mundo y Sky?",
