    faq_a_new_me_menu_build: "Primero, el cuestionario pregunta qué comidas haces y cuándo (2 comidas + un tentempié, 2 comidas + una cena ligera, o ambas), y si hay algo por la noche – para comer o para beber, qué y a qué hora. Con «2 comidas + un tentempié», las comidas son el almuerzo (11:30) y la cena (19:00), con el tentempié a las 16:00. Luego aparecen todas las opciones de esas comidas. Elige hasta 2 favoritas por comida: el menú muestra «esto o aquello». En algunas opciones (pita y crema, copos de maíz con leche, algo ligero) eliges hasta 3 cosas que te gusten, cada una en su porción, y el menú muestra «esto o aquello o lo otro»; las calorías se ajustan a lo que elijas. El café y las bebidas funcionan igual. Cada elección se equilibra, así que el día suma exactamente 1.300 o 1.500. Para cambiarlo cuando quieras: ⚙️ Ajustes → 🍽️ Crea tu menú, o «Elige hasta 3 que te gusten» en la tarjeta de la comida.",
    faq_q_new_me_menu_build: "¿Cómo se crea el menú de New Me?",
