    faq_a_myday_water_toggle: "Sí. El vaso de agua en «Mi Día» (con + para un vaso más) aparece por defecto. Para ocultarlo, desactiva «Mostrar el agua en “Mi Día”» en Ajustes > Personalización y calendario. No se borra nada: Control de Agua sigue funcionando, y al volver a activarlo el vaso vuelve.",
    faq_q_myday_water_toggle: "¿Puedo ocultar el agua en «Mi Día»?",
    myday_water_toggle_label: "Mostrar el agua en «Mi Día»",
    faq_a_routine_newme_sync: "Con New Me, el ⚙️ de Mi Rutina tiene un interruptor «Sincronizar con New Me». Activado (por defecto), las comidas de hoy de New Me aparecen en Mi Día y en Mi Rutina, en lugar de las comidas de la rutina que se ocultaron. Desactivado, las comidas de New Me salen de ambos y la rutina vuelve exactamente a como era. No se borra nada: al activarlo de nuevo vuelve todo y pregunta qué comidas de la rutina ocultar.",
    faq_q_routine_newme_sync: "¿Cómo activo o desactivo la sincronización de New Me con Mi Rutina y Mi Día?",
