    faq_a_food_list_languages: "La lista de alimentos integrada empezó con comidas israelíes y sus nombres en hebreo. En los demás idiomas cada alimento aparece con su nombre en inglés, y la búsqueda encuentra cualquier nombre en inglés que conozca (por ejemplo, 'broth' encuentra Clear soup); los alimentos que solo tienen nombre en hebreo no aparecen. Lo que no esté en la lista se puede escribir con tus propias palabras: la estimación con IA funciona en todos los idiomas.",
    faq_q_food_list_languages: "¿Por qué la lista de alimentos muestra nombres en inglés, y menos alimentos, en mi idioma?",
    settings_copyright_line: "© 2026 todos los derechos reservados. app desarrollada por eden zabari.",
    workout_ready_replace_btn: "Reemplazar",
    faq_a_sport_workout_ai: "En Mis entrenamientos → ⋯ → Plan con IA (y, con la tabla vacía, también en el mosaico junto a los planes listos). Responde con unos toques – cuántas veces por semana, cuándo, lugar, nivel y objetivo, casi todos también con \"Otro\" – y, si quieres, añade una línea libre, como una rodilla sensible o correr 5 km antes del verano. La IA crea una semana completa: tipos de entrenamiento, días, horas, duración, intensidad, ejercicios y días de descanso. Nada se guarda antes de una vista previa: \"Ponerlo en mi tabla\" (en lugar de la tabla o además de ella), \"Otra sugerencia\" (hasta 3 veces) o \"Cambiar respuestas\". El plan es moderado a propósito, y si mencionas dolor o una lesión recibes opciones suaves y la recomendación de consultar a un profesional. Usa la misma cuota de IA que la agenda y la rutina: 5 veces gratis y 60 al mes con Premium.",
    faq_q_sport_workout_ai: "¿Cómo creo un plan de entrenamiento con IA?",
