    workout_ai_when_morning: "Mañana",
    workout_ai_when_noon: "Mediodía",
    workout_ai_when_ph: "p. ej. después del trabajo, o 17:30",
    workout_ai_working: "Creando tu plan…",
    faq_a_sport_workout_jar: "Cada tipo de entrenamiento tiene su propia estrella de color: correr rosa, caminar verde, natación azul, etc. Cada entrenamiento que registras esta semana, desde la tabla o por separado, deja caer su estrella en el frasco de arriba en Mis entrenamientos, y el frasco se va llenando hasta tu meta semanal (tócalo para cambiar la meta). Al llegar a la meta, el frasco brilla. El frasco pequeño de al lado cuenta cuántas semanas seguidas lo llenaste.",
    faq_q_sport_workout_jar: "¿Qué son las estrellas de colores y el frasco en Mis entrenamientos?",
    faq_a_sport_workout_gcal: "Sí: en ⋯ → Google Calendar (una vez conectado Google Calendar en Ajustes). Cada entrenamiento con hora se convierte en un evento que se repite cada semana en sus días, y los cambios en la app lo actualizan. Los recordatorios llegan solo desde la app, así que Google no añade los suyos, y los entrenamientos nunca aparecen dos veces en la app. Al tocarlo otra vez se quitan de Google Calendar solo los entrenamientos.",
    faq_q_sport_workout_gcal: "¿Pueden aparecer mis entrenamientos en Google Calendar?",
    workout_gcal_btn: "Google Calendar",
    workout_gcal_error: "No se pudo actualizar Google Calendar; se intentará de nuevo con el próximo cambio",
    workout_gcal_not_connected: "Primero conecta Google Calendar en Ajustes",
    workout_gcal_off_toast: "Los entrenamientos se quitaron de Google Calendar",
    workout_gcal_on_toast: "Tus entrenamientos están en Google Calendar",
    faq_a_sport_workout_reminder: "Sí: en un entrenamiento, Recordatorio: 10 minutos, 30 minutos o una hora antes, o un tiempo personalizado (el entrenamiento necesita una hora). Suena como tus demás recordatorios, una vez y en un solo lugar: en la app si está abierta, si no en tu móvil. \"Hecho\" registra el entrenamiento en el historial, y \"Todavía no\" lo recuerda de nuevo en 5 minutos.",
    faq_q_sport_workout_reminder: "¿Puedo recibir un recordatorio antes de un entrenamiento?",
    workout_reminder_30min: "30 minutos antes",
    workout_reminder_label: "Recordatorio",
    workout_reminder_need_time: "Añade una hora para recibir un recordatorio",
    faq_a_sport_workout_share: "En ⋯ → Compartir, la semana se convierte en una imagen de cristal con los colores de tu tema y un enlace discreto a la app (en el móvil va directo al menú de compartir; en la computadora la imagen se guarda). ⋯ → PDF para imprimir abre una página limpia con toda la semana y una casilla junto a cada entrenamiento y ejercicio: elige \"Guardar como PDF\" o imprímela. El plan también aparece en el informe de datos de Ajustes, en Deporte.",
    faq_q_sport_workout_share: "¿Cómo comparto o imprimo mi semana de entrenamiento?",
    share_image_saved: "La imagen se guardó: puedes adjuntarla",
    share_save_image: "Guardar la imagen",
    workout_pdf_btn: "PDF para imprimir",
    workout_share_btn: "Compartir",
    faq_a_sport_workout_board: "En ⋯ → Tablero semanal cada día es una columna: arrastra un entrenamiento a otro día (en el móvil, mantén pulsado primero). En un entrenamiento, \"También en Mi Rutina\" lo pone en tu rutina a su hora y días, y los cambios se sincronizan en ambos sentidos; desde un elemento de Mi Rutina, \"Añadir a mis entrenamientos\" hace lo contrario. Un ✓ en cualquiera de los dos cuenta en ambos, y en Mi Día aparece una sola vez: en el chip junto al agua.",
    faq_q_sport_workout_board: "¿Cómo muevo un entrenamiento a otro día y lo enlazo con Mi Rutina?",
    routine_in_workouts_btn: "Abrir en mis entrenamientos",
    routine_to_workout_btn: "Añadir a mis entrenamientos",
    routine_to_workout_done: "Añadido a mis entrenamientos 💪",
    workout_delete_confirm_routine: "Se quitará del plan y de Mi Rutina. Los entrenamientos ya registrados en el historial se quedan.",
    workout_moved: "Movido al {day}",
    workout_routine_need_time: "Añade una hora para ponerlo en Mi Rutina",
    workout_routine_toggle: "También en Mi Rutina",
    workout_view_board: "Tablero semanal",
    workout_view_timeline: "Línea de tiempo",
    faq_a_sport_workout_plan: "En Seguimiento de Entrenamientos, en \"Mis entrenamientos\": + Entrenamiento – tipo, días, hora, duración, intensidad y lugar (también \"Otro\"). Los entrenamientos de fuerza, funcionales y de natación pueden llevar una lista de ejercicios, y Descanso marca un día de descanso. También puedes empezar con un plan listo. El entrenamiento de hoy aparece en grande, con toda la semana debajo; ✓ lo registra en el historial de entrenamientos junto con su intensidad. En ⋯ fijas una meta semanal (entrenamientos o minutos): cada entrenamiento que haces deja caer su estrella en el frasco.",
    faq_a_sport_workout_today: "En Mi Día, junto al agua, un pequeño chip muestra el entrenamiento de hoy: al tocarlo se abren los detalles, ✓ y ▶. ▶ inicia un temporizador que sigue corriendo en el chip de la pantalla de inicio, y \"Terminar\" registra el entrenamiento con el tiempo real. Si el reto \"Dos semanas de movimiento\" de New Me está activo, un entrenamiento registrado cuenta en él solo.",
    faq_q_sport_workout_plan: "¿Cómo planifico mi semana de entrenamiento?",
    faq_q_sport_workout_today: "¿Dónde veo el entrenamiento de hoy y cómo funciona el temporizador?",
