    faq_a_new_me_magic_themes: "Cinco temas brillantes que vienen con New Me: Bosque encantado, Polvo de estrellas, Hada de las rosas, Aurora mágica y Atardecer dorado. Elige uno dentro de New Me (⚙️ Ajustes > Colores) o en Ajustes > Apariencia y pantalla, y un pincel de destellos pinta la pantalla con él. Un tema mágico añade destellos por toda la app y en cada toque. Puedes volver a cualquier otro tema cuando quieras.",
