    apptour_focus_text: "Todo se aparta menos lo único de ahora, con un ✓ grande. Después aparece lo siguiente.",
    apptour_m_presets_text: "Tus comidas guardadas en un solo lugar: búsqueda, usadas hace poco, por hora del día, y ＋ añade una a hoy.",
    apptour_night_text: "🌙 oscurece toda la app; ☀️ trae de vuelta el día.",
    apptour_noteline_text: "Escribe y toca ➤: se guarda en tus notas. 📝 al principio cambia a 🛒 compras o a 🍎 una comida guardada.",
    apptour_search_text: "Notas, compras, calendario, recetas, cuadernos, metas, tablas y libros: una sola búsqueda lo encuentra todo.",
    faq_a_new_me_ai_menu: "Antes del menú, el cuestionario pregunta qué comidas haces y cuándo (2 comidas + un tentempié, 2 comidas + una cena ligera, o ambas), si tomas algo pequeño por la noche y a qué hora, qué no comes y cómo tomas el café o el té. Luego la IA crea 3 opciones para cada comida – cada una del tamaño de su parte del día, así que el día sigue sumando exactamente 1.300 o 1.500 – y también ideas de bebidas, que se guardan como tus bebidas fijas. Elige hasta 2 favoritas por comida; las opciones del menú original están justo debajo, y en 🔄 Cambiar aparecen después de tu menú personal. 🔄 Otras opciones crea una tanda nueva (3 veces por cuestionario). Para cambiar tus respuestas o crear un menú nuevo cuando quieras: ⚙️ Ajustes → ✨ Menú personal (IA).",
    faq_q_new_me_ai_menu: "¿Cómo funciona el menú personal de New Me?",
    nm_ai_menu_building: "Preparando un menú para tus comidas y horarios…",
    nm_ai_menu_drinks: "Bebidas para ti",
