    apptour_s_gcal_inside_text: "Conecta Google Calendar una sola vez y los eventos y tareas se sincronizan en ambos sentidos.",
    apptour_s_menu_text: "Aquí está todo lo que puedes ajustar, en cinco grupos. Vamos a abrirlos 👇",
    apptour_skip_part: "Saltar esta parte",
    apptour_start: "Empezar el recorrido",
    nm_sales_premium: "Incluye todo Premium",
    nm_unlock_premium: "Y todo Premium también se ha desbloqueado.",
    settings_sub_status_newme: "Premium está incluido en tu New Me.",
    room_back_to_shelf: "Al estante",
    faq_a_new_me_day_total: "Cada día cuadra exactamente con el plan: las comidas, unas 150 calorías para café y bebidas durante el día y lo que se eligió para la noche – algo pequeño para comer o algo para beber. Para la noche, elige hasta 3 que te gusten (por ejemplo un plátano, un yogur o 2 onzas de chocolate negro; o una infusión, té con un poco de leche o leche caliente), y sus calorías se quitan de las comidas. Cada elección se equilibra sola: una opción más pequeña o más grande, una comida quitada, el desayuno pequeño y la comida pequeña que lo acompaña, o la noche – la diferencia se suma a las comidas o se resta de ellas, a cada una según su tamaño, y debajo de cada comida pone cuánto (+ o −) y qué añadir o quitar. Una comida ya marcada se queda como se registró. En el cuestionario, cada comida muestra su ajuste, y un pequeño recuadro muestra comidas, bebidas, la noche y el total. ¿Te apetece otra cosa ese día? Mantén el total en las mismas calorías o menos.",
    faq_q_new_me_day_total: "¿Cómo suma un día de New Me exactamente 1.300 / 1.500, y dónde cuentan las bebidas?",
    nm_budget_chosen: "Menú elegido ~{n} · {adj} en las comidas",
