    nm_extra_line_fill: "{n} calorías para esta comida, para que el día sume {plan} – por ejemplo {ideas}",
    nm_less_ideas_l: "una rebanada de pan y una cucharada de tahini menos, o la mitad de los carbohidratos",
    nm_less_ideas_m: "una rebanada de pan menos, o una cucharada menos de tahini",
    nm_less_ideas_s: "una cucharadita menos de aceite o tahini",
    nm_less_line: "{n} calorías en esta comida, para que el día sume {plan} – por ejemplo {ideas}",
    nm_less_line_late: "{n} calorías en esta comida, para algo pequeño a las {time} – por ejemplo {ideas}",
    nm_swap_balanced: "{n} calorías repartidas entre las comidas, para que el día sume {plan}",
    books_quotes_chip: "Citas",
    faq_a_book_quotes: "En el estante de la habitación secreta (Citas), o con la pequeña etiqueta 💬 Citas del Rincón de lectura: es la misma lista. Toca \"+ Cita\", escribe la frase y elige el libro de tu Rincón de lectura, o escribe otro título con \"✏️ Otro\"; el autor es opcional. ✏️ edita una cita y 🗑️ la elimina. Las citas son marcapáginas que se deslizan: 🎨 arriba cambia a fotos o a un muro de tarjetas.",
    faq_a_room_wish_jar: "En el estante de la habitación secreta hay un frasco de cristal para los sueños. Toca el frasco pequeño del estante de arriba (o Estante > El frasco de deseos) y escribe cómo te gustaría que fuera tu vida: lo más loco que quieras, sin bien ni mal. Cada deseo se dobla en una nota y cae al frasco. «Sacar una nota» abre una al azar, y cada nota también se puede abrir por separado. A partir de la segunda vez que abres el mismo deseo, puedes convertirlo en una meta y dividirlo en pasos pequeños. Una vez por semana aparece con suavidad una nota con uno de tus deseos: sin presión, solo un recordatorio de hacia dónde vas.",
    faq_q_book_quotes: "¿Dónde guardo las citas de libros que me encantaron?",
    faq_q_room_wish_jar: "¿Qué es el frasco de deseos de la habitación secreta?",
