    room_wish_new_ph: "¿Cómo quiero que sea mi vida? Sueña lo más loco que quieras, sin bien ni mal: solo lo que sientes…",
    room_wish_new_title: "Un deseo nuevo",
    room_wish_pop_jar: "Abrir el frasco",
