    room_wish_to_goal: "🎯 Convertirlo en una meta, en pasos pequeños",
    room_wish_written: "Escrito el {date}",
    faq_a_saved_meals_page: "Las comidas guardadas tienen su propia página: Nutrición y Métricas > ⭐ Comidas guardadas (o ⭐ en el menú). La búsqueda de arriba encuentra una comida por nombre o ingrediente, \"Usadas hace poco\" muestra lo que añadiste últimamente y las pestañas (Desayuno, Almuerzo, Cena, Sopas…) muestran cada momento del día. \"+ Hoy\" añade una comida al Registro Diario de Comidas de hoy, en el siguiente hueco libre. Toca una comida para editarla o eliminarla, y ＋ arriba añade una nueva.",
    faq_q_saved_meals_page: "¿Dónde encuentro y gestiono mis comidas guardadas?",
