    presets_tab_noon: "Almuerzo",
    presets_tab_snack: "Tentempiés",
    presets_tab_soup: "Sopas",
    presets_tab_sweet: "Dulces",
    faq_a_notes_sticky_look: "Las notas son una lista corta de tarjetas de cristal: 🎨 arriba en Notas cambia el aspecto de todas las Notas (la lista, los botones de los días de arriba y la ventana donde se escribe una nota): cristal, lista limpia, fichas o cinta washi. Una nota que se arrastra conserva exactamente su propio aspecto y color. Toca el texto de una nota para abrirla: allí puedes editarla, cambiar sus colores y ver cuándo se escribió por última vez. Toca ○ cuando esté hecha, y × la mueve al archivo (🗑️ al final de la lista la recupera). Arrástrala por ⠿ para cambiar el orden, debajo de «Más tarde» o a un día de arriba. ! marca una nota como urgente: sube suavemente a las primeras filas con una pequeña etiqueta «Urgente»; otro toque la quita.",
    faq_q_notes_sticky_look: "¿Cómo abro, edito o quito una nota?",
    note_to_archive_btn: "Mover al archivo",
    faq_a_routine_clash: "Si a esa hora ya hay algo en los mismos días, hay dos opciones: \"Sustituir\" – lo nuevo ocupa esa hora y eliges a qué hora pasa lo que había (al editar algo que ya existe, se propone su hora anterior, así que simplemente se intercambian), o \"Los dos\" – ambos se quedan a la misma hora, uno debajo del otro. Si los días son distintos (por ejemplo, uno de domingo a jueves y el otro el viernes), no se pregunta nada.",
    faq_q_routine_clash: "¿Qué pasa si pongo algo en la rutina a una hora que ya está ocupada?",
    routine_clash_both: "✌️ Los dos – ambos a las {time}",
    routine_clash_move_btn: "Mover y guardar",
    routine_clash_move_to: "¿A qué hora mover \"{title}\"?",
    routine_clash_replace: "🔄 Sustituir – y mover \"{title}\" a otra hora",
    routine_clash_title: "A las {time} ya hay: {title}",
    faq_a_new_me_coffee: "Debajo del menú de hoy hay un breve resumen: cuántas calorías suman todas las comidas del día, cuánto queda para café y bebidas, y botones con el café y las bebidas elegidos – con un toque se añade a Bebidas. En «Elige hasta 3 que te gusten», debajo de los botones (y en el cuestionario), eliges qué aparece: agua / agua con gas, infusión, un refresco light, solo / americano (~5), té con un poco de leche (~25), café con agua y hasta 100 ml de leche o bebida vegetal (~50), chocolate caliente ligero, leche caliente o café normal / con leche (~120).",
    faq_q_new_me_coffee: "¿Dónde añado el café y cómo sé cuánto me queda del día?",
