    nm_late_idea_yogurt: "Yogur 0%",
    nm_late_ideas: "Por ejemplo: {ideas}",
    nm_late_ideas_none: "Queda muy poco hoy: té, agua o café solo",
    nm_late_room_line: "Algo pequeño antes de dormir · quedan ~{n} kcal hoy",
    faq_a_recipe_examples: "Debajo de tus recetas hay recetas de ejemplo: desayunos, ensaladas, sopas, platos principales, guarniciones, tentempiés, postres y platos veganos, cada una con el tiempo de preparación, las calorías por porción y cuántos gramos pesa una porción. Toca una receta para abrirla, y \"Guardar en Mis Recetas\" crea tu propia copia, que puedes editar. Las etiquetas de categoría filtran, y al tocar la misma etiqueta otra vez se ve todo.",
    faq_a_recipe_grams: "Dentro de una receta, junto a las calorías, pone \"1 porción ≈ X g\". En tus propias recetas, rellena \"Gramos por porción\" (y el tiempo de preparación, si quieres) en el formulario de la receta: los dos son opcionales, y el tiempo aparece en la franja de color de la receta.",
    faq_q_recipe_examples: "¿Qué son las recetas de ejemplo de Mis Recetas?",
    faq_q_recipe_grams: "¿Cómo veo cuántos gramos tiene una porción?",
    recipe_category_vegan: "Vegano",
    recipe_grams_placeholder: "Gramos por porción",
    recipe_meta_grams: "1 porción ≈ {n} g",
    recipe_meta_grams_short: "{n} g",
    recipe_meta_minutes: "{n} min",
    recipe_minutes_placeholder: "Tiempo de preparación (minutos)",
    recipe_save_example_btn: "Guardar en Mis Recetas",
    recipe_saved_example: "✓ Guardada en Mis Recetas",
    recipe_saved_example_toast: "Guardada en Mis Recetas: ahí puedes editarla",
    recipes_examples_title: "Recetas de ejemplo",
    faq_a_recipe_scan_multi: "Sí. En \"Añadir Receta\", toca 📷 y elige una foto o varias (hasta 6; también sirve un PDF). Cada una aparece en una lista corta donde eliges qué contiene: Todo, Ingredientes o Preparación, y \"➕ Otra foto\" añade más. Luego toca \"✨ Escanear la receta\": la IA lo une todo en una sola receta, en orden y sin líneas repetidas, y cuenta como un solo escaneo. Varias fotos elegidas desde 📷 Foto en el asistente de IA también se abren aquí.",
    faq_q_recipe_scan_multi: "¿Puedo escanear una receta a partir de varias fotos, por ejemplo los ingredientes y los pasos por separado, o dos páginas?",
    recipe_scan_add_more: "➕ Otra foto",
    recipe_scan_part_all: "Todo",
    recipe_scan_part_ingredients: "Ingredientes",
    recipe_scan_part_steps: "Preparación",
    recipe_scan_remove_photo: "Quitar la foto",
    recipe_scan_run_btn: "✨ Escanear la receta",
    recipe_scan_too_many: "Hasta {n} fotos por receta",
    faq_a_note_written_at: "Toca el texto de la nota para abrirla. Dentro, debajo del texto, aparece cuándo se escribió por última vez, con la fecha y la hora exactas. Solo un cambio en el propio texto lo actualiza: archivarla y restaurarla, marcarla ✓, los colores o moverla no lo cambian.",
    faq_q_note_written_at: "¿Cómo veo cuándo escribí una nota?",
    note_written_at: "Escrita por última vez: {date}",
    faq_a_new_me_month: "En la mochila mágica → Calendario mensual: cada día tiene un color según cuántas comidas se marcaron, las flechas ‹ › pasan de un mes a otro, y debajo del calendario aparece la media de calorías diarias del mes. Al tocar un día se ve cuántas comidas se marcaron y cuántas calorías se comieron ese día.",
    faq_q_new_me_month: "¿Dónde veo el mes hacia atrás y mi media de calorías en New Me?",
    nm_month_avg: "Media del mes: {kcal} calorías al día · días con registro: {n}",
    nm_month_day_empty: "No se registró nada este día.",
    nm_month_day_line: "Comidas marcadas: {checks} · calorías: {kcal}",
    nm_extra_line_small: "{n} calorías para esta comida, del desayuno pequeño – por ejemplo {ideas}",
    faq_a_new_me_small_breakfast: "Un desayuno ligero (unas 170 kcal): una pita de espelta (hasta 100 kcal) con una crema para untar o queso, además de una verdura – elige hasta 3 que te gusten, por ejemplo 1 cucharadita de crema de cacao, 1 cucharadita de mantequilla de cacahuete o una loncha de queso semicurado (hasta 22%). Como es pequeño, viene con «Y una comida pequeña más» a otra hora (una hora y media después, por ejemplo 11:30 → 13:00 – se puede elegir cualquier otra hora): otra pita y crema, yogur proteico y fruta, tortitas de arroz y queso, cereales con leche o media pita y huevos – hasta unas 200 kcal, con su propio ✓. Lo que aún sobra se reparte entre las demás comidas, y cada comida muestra cuánto se le añadió, así que el total del día queda como en el plan. Puedes elegirlo en el cuestionario o cambiar a él solo por hoy con 🔄 – por ejemplo, cuando desayunas tarde.",
    faq_q_new_me_small_breakfast: "¿Qué es el «desayuno pequeño» del menú de New Me?",
