    faq_a_ai_icon: "Sí, en Ajustes > Apariencia y pantalla. La burbuja suave es la predeterminada, y con Premium también puedes elegir un cerebro flotante o un robot.",
    faq_a_new_me_favorites: "Sí. En el cuestionario (y al repetirlo desde los ajustes) puedes elegir hasta 2 opciones para cada comida. La primera aparece en el menú, con una línea “o” debajo para la segunda: al tocarla cambias a ella solo por hoy. Y si el desayuno no se tomó a tiempo, “⏰ Más tarde” lo pasa a más tarde en el día, sin cambiar las calorías.",
    faq_a_theme_mode: "Algunos temas especiales lucen mejor en oscuro – Acuarela, Aurora boreal, Barbie y los dos temas de brillos –, así que al elegir uno de ellos la app pasa al modo oscuro, y al elegir cualquier otro tema (también el cohete) pasa al claro. Negro y Gris oscuro siguen oscuros. Siempre puedes cambiarlo después con 🌙 en el menú o con Modo Claro en los ajustes.",
    faq_a_water_month: "En el registro de agua. Cada entrada del registro de hoy muestra la hora en que se añadió, y \"Tabla mensual\" abre todo el mes: cada día muestra cuántos litros se bebieron (✓ cuando se alcanzó la meta diaria), y al tocar un día aparecen sus entradas con sus horas.",
    faq_q_ai_icon: "¿Puedo cambiar el icono del asistente de IA?",
