    dev_sim_panel_title: "PM – solo para ti",
    faq_a_new_me_weight_optional: "No. Tanto el peso actual como el peso objetivo del cuestionario son opcionales. Si más adelante se añade un pesaje (⚖️ Peso en «Mi camino» de New Me, o en el registro de peso), el progreso se cuenta desde el primero.",
    faq_q_new_me_weight_optional: "¿Tengo que escribir mi peso en New Me?",
    nm_unlock_desc: "El menú, los retos y el camino ya están listos: paso a paso, juntos.",
    nm_unlock_title: "¡New Me desbloqueado!",
    room_reveal_star: "Una nueva estrella se encendió en el telescopio de la azotea ✨",
    faq_a_room_records: "El tocadiscos está en la habitación desde el principio, sobre el tocón junto al sillón. Sus discos abren en YouTube los videoclips oficiales de grandes éxitos de los últimos años, y debajo hay cinco melodías tranquilas que suenan aquí mismo en la habitación: el disco gira mientras suenan, y «⏹ Parar» detiene la música.",
    faq_a_room_roof_gifts: "Llegan con la 8.ª llave. Un toque en el telescopio permite mirar a través de él: el cielo nocturno de cerca (arrastra, o usa las flechas, para mirar alrededor), y tus retos terminados forman en él una constelación, una estrella por cada reto; un toque en una estrella muestra cuál fue. Un toque en el cofrecito lo abre (por ahora está vacío) y otro toque lo cierra.",
    faq_q_room_records: "¿Qué hay en el tocadiscos de la habitación secreta?",
    faq_q_room_roof_gifts: "¿Qué son el telescopio y el cofre de la azotea?",
    room_chest_letter: "Una cartita para ti",
    room_chest_letter_1: "Cada pequeño paso del camino fue real, y todos cuentan.",
    room_chest_letter_2: "Tratarte con cariño es parte del camino, no una pausa en él.",
    room_chest_letter_3: "Hay días más ligeros y días más pesados. Estar presente en ambos es la verdadera fuerza.",
    room_chest_letter_4: "Descansar está permitido. Descansar también es avanzar.",
    room_chest_letter_5: "Los cambios que perduran son los tranquilos: se construyen día tras día.",
    room_chest_letter_6: "Hoy es un buen día para sentir orgullo, aunque sea un poquito.",
    room_chest_letter_7: "No hace falta hacerlo todo. Solo la siguiente cosa pequeña.",
