    dev_sim_lock: "Bloquear – verlo como antes de comprar",
    dev_sim_locked_toast: "🔒 Bloqueado – así se ve antes de comprar",
    faq_a_new_me_preview: "Sí. La página de New Me empieza con un video corto de lo que pasa dentro: el cuestionario, las lámparas del pasillo, la mochila, los retos y las llaves. Debajo está todo lo que incluye, un vistazo a un día y respuestas breves.",
    faq_q_new_me_preview: "¿Puedo ver New Me antes de comprarlo?",
    nm_trailer_c1: "Un cuestionario corto – y tu menú está listo",
    nm_trailer_c2: "Cada comida es una lámpara en tu pasillo",
    nm_trailer_c3: "En la mochila: el menú de hoy, agua y compras",
    nm_trailer_c4: "Termina un pequeño reto – y recibe una llave",
    nm_trailer_c5: "Y detrás de cada puerta – algo solo para ti",
    nm_trailer_end: "Empezando hoy, paso a paso",
