    ai_chat_food_edit: "✏️ Corregir calorías / proteína",
    ai_chat_food_invalid: "Las calorías deben ser un número mayor que 0",
    ai_chat_food_updated: "Actualizado:",
    faq_a_ai_chat_food_fix: "Sí. Debajo de la respuesta en el chat, toca ✏️ Corregir calorías / proteína, cambia los números y toca Guardar. Solo cambia lo que se acaba de añadir, aunque se haya sumado a un snack que ya estaba. La IA puede equivocarse, así que vale la pena revisarlo.",
    faq_a_new_me_home_btn: "Si tienes New Me, un pequeño 💎 junto al modo enfoque, arriba en la pantalla de inicio, abre el menú de hoy. Las comidas de hoy también aparecen en Mi Día, cada una con su ✓.",
    faq_a_routine_item_days: "Sí. Toca el elemento en Mi Rutina y elige sus días en 📅 Días – por ejemplo, solo de lunes a viernes. Los demás días no aparece en Mi Día y no tiene ✓; en Mi Rutina se queda, más tenue, con sus días al lado. La tarjeta que pregunta por un elemento tras 3 días sin ✓ cuenta solo los días de ese elemento.",
    faq_q_ai_chat_food_fix: "¿Puedo corregir las calorías o la proteína después de que el asistente registre comida?",
    faq_q_new_me_home_btn: "¿Dónde está New Me en la pantalla de inicio?",
    faq_q_routine_item_days: "¿Un elemento de Mi Rutina puede ser solo ciertos días?",
    routine_item_days_label: "📅 Días",
    home_note_meal_ph: "Busca una comida guardada…",
    menu_quick_search: "Búsqueda rápida",
    nm_times_hint: "Consejo: puedes poner la hora más tardía a la que sueles hacer cada comida; por ejemplo, las 9:00 si sueles comer hacia las 8.",
    room_game_marquee: "De camino, nos paramos a disfrutar",
    room_sand_erase_aria: "Frota para borrar lo escrito",
    faq_a_home_note_line: "Escribe en la línea del centro de la pantalla de inicio y toca ➤ (o Intro): se guarda en Notas. Toca 📝 al principio de la línea y cambia a 🛒: entonces lo que escribas va a la Lista de Compras. Tócalo una vez más para 🍎: escribe unas letras, aparecen tus comidas guardadas que coinciden y con un toque se registra una en las comidas de hoy. Con 🎤 puedes decirlo en voz alta.",
    faq_a_night_mode: "Abre el menú ☰ y toca 🌙 arriba: toda la app se vuelve oscura. ☀️ en el mismo lugar devuelve el día. También está en Ajustes, en Modo Claro.",
    faq_q_home_note_line: "¿Cómo escribo una nota rápida desde la pantalla de inicio?",
    faq_q_night_mode: "¿Cómo paso al modo noche?",
    menu_day_mode: "Modo día",
    menu_night_mode: "Modo noche",
    faq_a_secret_room_yoga: "Al final del sendero del bosque hay un portal luminoso y, detrás, junto a una cascada, las criaturas del bosque – Lumi, Puffi, Nixie y Sparklet – se sientan en sus esterillas en semicírculo, y Flora, la profesora de yoga, se sienta frente a ellas en la única esterilla que hay sobre la piedra. Toca a Flora: abre los ojos, todo se acerca y la charla empieza despacio, con tiempo para leer: Flora pregunta cómo están todos, cada criatura responde con su propio nombre (con un pequeño dibujo de quien habla junto a cada línea) y luego ella te pregunta cómo te sientes con las personas cercanas. La charla sigue según tus respuestas: gente buena, alguien con quien cuesta o algo de soledad. Cada camino termina con una pequeña misión (puede ir directo a Mi Día; cuando la misión es escribir algo, hay un lugar para escribirlo y se guarda en el diario mágico) y una postura con tres respiraciones en grupo. ↩ vuelve un paso atrás y ✦ empieza una charla nueva. La siguiente llave abre la cascada: al sentarte en la piedra todo desaparece y solo queda el sonido del agua. Al asomarte a la poza, una pregunta sube del agua –¿qué haría hoy tu verdadero yo?– y la respuesta se convierte en una pequeña tarea en Mi Día. Es un momento amable, no un sustituto de hablar con un profesional.",
    faq_q_secret_room_yoga: "¿Qué pasa en el yoga del bosque?",
    room_back_to_forest: "Volver al sendero",
    room_back_to_yoga: "Volver al yoga",
    room_item_waterfall: "La cascada",
    room_waterfall_pool_aria: "Tocar el agua",
    room_waterfall_rock_aria: "Sentarse en la roca",
    room_yoga_guide_aria: "Hablar con Flora",
    yg_g_alone: "Gracias por compartirlo. A todos nos pasa a veces.",
    yg_g_alone_q: "¿Qué te haría bien, aunque sea un poquito?",
    yg_g_critic: "Una crítica puede doler mucho tiempo. Habla de un momento, no de toda la persona.",
    yg_g_end: "Gracias por venir al círculo. Puedes volver cuando quieras.",
    yg_g_gate: "Está permitido poner un límite. Un límite no es un muro: es una puerta.",
    yg_g_good: "Qué bonito 💛 ¿Quién te hizo bien esta semana?",
    yg_g_good_msg: "Vale la pena decírselo a la gente buena. Un pequeño gracias puede alegrarles todo el día.",
    yg_g_hard: "Gracias por decirlo. ¿Qué es lo que más te pesa?",
    yg_g_listen: "Que no te escuchen cansa. Tu voz importa, aunque sea bajita.",
    yg_g_new: "La gente nueva empieza con un pequeño hola. Una clase, un paseo, un grupo: un paso.",
    yg_g_old: "Alguien que ya te conoce es un lugar cálido. Basta con un mensaje corto.",
    yg_g_start: "Y ahora te toca a ti 🌿 ¿Cómo te sientes últimamente con las personas cercanas?",
    yg_g_used: "Cuando damos y no recibimos nada, algo por dentro se cansa. Está bien notarlo.",
    yg_name_guide: "Flora",
    yg_name_p1: "Lumi",
    yg_name_p2: "Puffi",
