    yg_o_partner: "Mi pareja",
    yg_o_used: "Siento que se aprovechan de mí",
    yg_p1_alone: "Aquí estamos 💛",
    yg_p1_good: "¡Qué lindo escucharlo! Me alegró el corazón.",
    yg_p1_start: "Mi semana fue intensa, pero una buena amiga me llamó justo a tiempo.",
    yg_p2_hard: "A mí también me pasó. Solo decirlo en voz alta ya me ayudó.",
    yg_p2_start: "A mí también me ayuda escuchar a todos.",
    yg_pose_child: "Ahora la postura del niño 🌙 Rodillas abajo, frente en la esterilla: un lugar seguro para respirar. Tres respiraciones en grupo.",
    yg_pose_heart: "Ahora corazón abierto 💗 Hombros atrás, pecho amplio. Tres respiraciones en grupo.",
    yg_pose_tree: "Ahora la postura del árbol 🌳 De pie y firme, un pie sobre la otra pierna, manos arriba. Tres respiraciones en grupo.",
    yg_task_good: "Enviar hoy un pequeño mensaje de agradecimiento",
    yg_task_hard: "Escribir una frase que me gustaría decir",
    yg_task_new: "Encontrar un lugar para conocer gente nueva",
    yg_task_old: "Enviar «pensé en ti» a alguien",
    nm_time_hour: "Hora",
    nm_time_minutes: "Minutos",
    routine_time_taken: "Ya hay algo a esta hora: {title}",
    faq_a_new_me_times: "En el cuestionario del principio y, en cualquier momento, en los ajustes de New Me → «Horarios de comida». Si tu rutina ya tiene horarios de comidas, se toman de ahí – y se pueden ocultar las comidas de la rutina y mostrar en su lugar las de New Me. Si no, eliges cuántas comidas al día (2 comidas + un tentempié / 2 comidas + una cena ligera / 2 comidas + un tentempié + una cena ligera) y cuándo es cada una. Con «2 comidas + un tentempié» son el almuerzo a las 11:30, un tentempié a las 16:00 y la cena a las 19:00 (cualquiera se puede cambiar). Estos son tus horarios de comida en todas partes: en el pasillo, en Mi Día, en Mi Rutina y en los recordatorios. Elijas lo que elijas, las calorías del día no cambian: lo que se quita se reparte entre las demás comidas.",
    faq_q_new_me_times: "¿Cómo fijo mis horarios de comida en New Me?",
    nm_times_count: "¿Cuántas comidas al día?",
    nm_times_from_routine: "Sí, tomarlos de mi rutina",
    nm_times_hide: "Ocultar las comidas de mi rutina y mostrar en su lugar las de New Me",
    nm_times_later: "Más tarde",
    nm_times_manual: "No, elegir aquí",
    nm_times_none_found: "Tu rutina todavía no tiene comidas: elige aquí cuántas y cuándo.",
    nm_times_q: "¿Tu rutina tiene horarios fijos para comer?",
    nm_times_saved: "Horarios de comida guardados",
    nm_times_title: "Horarios de comida",
    faq_a_routine_exact_time: "Sí. Cuando le describes una rutina a la IA con una hora exacta (como \"16:10 trading\"), se guarda tal cual, sin redondear a la hora en punto. Todo lo que está anotado en tu rutina aparece siempre en el tablero, aunque su hora no esté elegida en los ajustes de horas, y quitar una hora que tiene algo anotado pide confirmación primero. También puedes cambiar una hora a mano: toca la hora en la ventana del elemento y elige la hora y los minutos.",
    faq_q_routine_exact_time: "¿Puede mi rutina tener una hora exacta, como 16:10?",
    room_item_sand: "Escribir en la arena",
    room_item_yoga: "Yoga en el bosque",
    room_sand_ph: "¿Qué te gustaría soltar?",
    room_sand_write: "Escribir",
    room_song_1: "Para Elisa · Beethoven",
    room_song_2: "Himno de la alegría · Beethoven",
    room_song_3: "Canon en re · Pachelbel",
    room_song_4: "Gymnopédie n.º 1 · Satie",
    room_song_5: "Greensleeves · tradicional",
    room_vinyl_stop: "⏹ Parar",
    routine_hour_remove_text: "Lo que está anotado a esta hora se borrará de la rutina: {title}",
    routine_hour_remove_title: "¿Quitar {time}?",
    faq_a_routine_ai: "En Mi Rutina, abre ⚙️ (o ➕) y toca \"Una rutina nueva con IA\": describe la rutina con palabras sencillas – por ejemplo \"despertar a las 7, gimnasio a las 8, trabajo hasta las 17\" – y la IA arma una pestaña nueva con las horas y las tareas. Si el texto dice qué días (\"entre semana\"), la pestaña se abre esos días, y rutinas distintas para días distintos se convierten en pestañas separadas. Después todo se puede editar como siempre.",
    faq_a_routine_daysoff: "En Mi Rutina, toca ➕ y luego \"Días libres\": elige los días (por ejemplo sábado y domingo) y cuál es la rutina en ellos – sin horario (queda despejado), tu propia rutina, o contarle a la IA qué haces para que la arme. Los días libres tienen su propia pestaña, y esos días Mi Rutina y Mi Día muestran solo esa pestaña.",
    faq_q_routine_ai: "¿Cómo creo una rutina con IA?",
    faq_q_routine_daysoff: "¿Cómo marco días libres en Mi Rutina?",
    routine_add_ai: "Una rutina nueva con IA",
    routine_add_daysoff: "Días libres",
    routine_ai_create: "Crear la rutina",
    routine_ai_default_name: "Rutina nueva",
