    routine_ai_limit: "La cuota de IA de este mes se agotó – se reinicia el mes que viene",
    routine_ai_ph: "¿Cuál es la rutina? p. ej. despertar a las 7, gimnasio a las 8, trabajo de 9 a 17, cena a las 19. También se pueden decir los días.",
    routine_ai_working: "Creando la rutina…",
