    routine_daysoff_ai: "Contarle a la IA qué hago",
    routine_daysoff_ai_ph: "p. ej. despertar a las 9, un desayuno largo, un paseo por la tarde, familia por la noche",
    routine_daysoff_clean: "Sin horario – que quede despejado",
    routine_daysoff_clear_q: "¿Vaciar la rutina de los días libres?",
    routine_daysoff_done: "La rutina de los días libres está lista 🌴",
    routine_daysoff_done_clean: "Los días libres quedan despejados 🌿",
    routine_daysoff_empty: "Un día libre – sin horario 🌿",
    routine_daysoff_own: "Mi propia rutina",
    routine_daysoff_pick_days: "Elige al menos un día",
    routine_daysoff_what: "¿Y cuál es la rutina esos días?",
    routine_daysoff_which: "¿Qué días?",
    faq_a_secret_room_diary: "Solo tú. Las páginas del diario se guardan en tu cuenta, así que están en todos tus dispositivos y nadie más puede verlas. Se abre desde el diario mágico que está sobre el escritorio de la habitación secreta, y también desde el diario del rincón de la música. Debajo de la página nueva hay una tabla mensual plegada: un punto marca cada día que tiene una página, y al tocar un día se abren sus páginas; ahí también se puede borrar una página. Cuando el diario ya está abierto, también se puede añadir al menú principal, con el interruptor del propio diario o en los ajustes de New Me.",
    faq_a_secret_room_places: "Cada entrada del portal del bosque se abre con su propia llave. Detrás: el porche frente al mar (en la mesita, la lámpara de Aladino: un toque y un espíritu del bosque sale de ella en una niebla mágica, da vueltas y empieza una conversación sobre tu deseo, mira «¿Qué hace el genio de la lámpara?»), la guitarra y el diario (la guitarra toca una melodía corta y tranquila y se detiene sola, y cada uno de los tres discos que cuelgan del árbol toca su propia melodía mágica –otro toque la detiene–, y el diario sobre el tocón es para escribir), la sala de respirar (un lago tranquilo al atardecer; sobre el agua flota un farolillo de loto: tócalo, escribe un deseo y se aleja con él, lejos, hacia el fondo del lago; con la varita mágica puedes escribir en la arena lo que quieres soltar, y se queda hasta que lo borras con el dedo) y el sendero del bosque (se abre de noche, y al tocar los faroles pasa a ser de día; de la gran rama cuelga un columpio mágico, el banco es para sentarse, y al tocar el cartel se acerca: un tablón con seis preguntas pequeñas para marcar). En una entrada cerrada se ve cuántas llaves faltan. Al final del sendero, un portal luminoso lleva al yoga junto a la cascada y, desde allí, a la propia cascada.",
    faq_q_secret_room_diary: "¿Quién ve el diario?",
    faq_q_secret_room_places: "¿Qué hay detrás de las puertas del pasillo?",
