    ai_chat_working_table: "Un momento, creando la tabla…",
    dev_weather_preview_label: "Vista previa – solo en tu cuenta:",
    faq_a_ai_chat: "Toca la burbuja y se abre un chat. Elige qué hacer – algo para el calendario, lo que comiste, una foto de una receta o una tabla nueva – o simplemente escribe, y el asistente lo entiende solo. También puedes tocar 🎙️ y hablar en lugar de escribir. Para el calendario puedes elegir una vez, cada semana o cada día. La respuesta llega en el chat, y desde ahí puedes seguir con otra cosa o abrir el calendario / lo que comiste.",
    faq_a_new_me_hall: "New Me se abre en el portal de un bosque mágico, y cada entrada es un lugar: la puerta redonda del árbol gigante lleva a la habitación secreta, el tronco hueco al porche frente al mar, la casita de seta a la guitarra y el diario, el pequeño arco de sauce a la sala de respirar, el gran arco de sauce al sendero del bosque, y el arco de flores con la escalera sube a la azotea de estrellas cuando se abre. En una entrada cerrada se ve un candado. Tu personaje, Sky, flota sobre el sendero, y alrededor están los botones del juego: la siguiente misión, el reto de la semana, la mochila mágica con todo New Me, el mapa del mundo y las herramientas. Al tocar las llaves de arriba se explica cómo se ganan las llaves.",
    faq_a_new_me_routine_meals: "Cuando hay comidas definidas en New Me y Mi Rutina también tiene comidas, New Me pregunta si ocultarlas y mostrar en su lugar las comidas de New Me, para que nada aparezca dos veces. Entonces Mi Rutina muestra las comidas de New Me a sus horas, con 💎 y un ✓; al tocar el nombre de una comida se abre una ventana para elegir otra comida o cambiar su hora, allí mismo sobre la rutina. No se borra nada: vuelven desde ⚙️ Ajustes de New Me → Comidas en la rutina, o desactivando «Sincronizar con New Me» en el ⚙️ de Mi Rutina. Sin un New Me activo vuelven solas.",
    faq_a_room_computer: "Es un pequeño chat que empieza con «¿Qué tal va tu día hasta ahora?» – bien, ajetreado o difícil – y sigue contigo paso a paso, hasta una pequeña misión al final (que también puede ir directo a Mi Día). Las respuestas se pueden tocar o escribir libremente: lo que se escribe se conecta con la respuesta más cercana. «↩ Atrás» vuelve un paso para responder de otra manera, y «Chat nuevo» empieza de cero en cualquier momento. Después de un día ajetreado o difícil puedes volver al ordenador más tarde el mismo día: «He vuelto...» continúa la conversación. La luz verde de abajo apaga y enciende el ordenador. Solo se guardan las elecciones, solo en este dispositivo y solo hasta el final del día.",
    faq_q_ai_chat: "¿Cómo hablo con el asistente?",
    faq_q_new_me_hall: "¿Qué es el pasillo de New Me?",
    faq_q_new_me_routine_meals: "¿Por qué Mi Rutina muestra las comidas de New Me?",
    faq_q_room_computer: "¿Cómo funciona el ordenador de la habitación secreta?",
