    dictation_btn_aria: "Habla y se escribe",
    dictation_mic_denied: "El micrófono está bloqueado: permítelo desde el 🔒 junto a la barra de direcciones o en los ajustes del teléfono",
    faq_a_dictation: "Sí: toca el micrófono 🎤 en la esquina de la nota rápida o de una página de escritura del cuaderno, y habla: las palabras se escriben mientras hablas, en el idioma de la app. Tócalo otra vez para parar. La primera vez, el navegador pide permiso para usar el micrófono. Funciona en Chrome / Android y en Safari en el iPhone. En la computadora hace falta un micrófono y un navegador como Chrome, Edge o Safari; si falta algo, el mensaje dice exactamente qué.",
    faq_q_dictation: "¿Puedo hablar en lugar de escribir?",
    faq_a_secret_room: "Una habitación solo tuya en New Me: una casa dentro de un árbol gigante. Ves una pared cada vez y giras con las flechas (o deslizando). La primera llave llega tras un ✓ en una comida en 3 días distintos y abre la puerta, y con ella toda la habitación: el ordenador, el juego, el tocadiscos, el estante con la biblioteca dentro y el gato. Después, cada reto terminado (también el reto de la semana) da una llave que abre el siguiente lugar: la azotea de estrellas, el porche frente al mar, la guitarra y el diario, la sala de respirar, el sendero del bosque con el yoga, la cascada y una sorpresa en la azotea; y el 8.º trae una botella del mar con la carta del pasado dentro. Cuando algo se abre, una flecha muestra el camino. También se abre la puertecita de abajo de la máquina de juegos; por ahora el armarito de detrás está vacío. En la azotea de estrellas, una estrella que tocas cae como una estrella fugaz, y el gato se sienta en el cojín.",
