    settings_good_things_label: "\"3 cosas buenas\" por la noche",
    settings_weather_hint: "Lluvia, nubes o nieve en el fondo de la pantalla de inicio, según el tiempo donde estás. Tu ubicación aproximada se queda en este dispositivo y se consulta a través de nuestro servidor con MET Norway.",
    settings_weather_label: "El tiempo en el cielo de la pantalla de inicio",
    weather_failed: "No pudimos consultar el tiempo ahora mismo.",
    weather_location_denied: "No hay acceso a tu ubicación – permítelo en los ajustes del navegador e inténtalo de nuevo.",
    faq_a_home_focus: "Toca ◎ arriba en la pantalla de inicio: todo desaparece menos lo único de ahora – lo que toca a esta hora, o lo siguiente de la lista de hoy – con un ✓ grande, y Nota Rápida. Después del ✓ aparece lo siguiente. Toca 'Modo enfoque ✕' arriba para que vuelva todo.",
    faq_a_home_search: "Abre el menú ☰: la búsqueda está justo arriba. Escribe al menos 2 letras: los resultados salen de tus notas, lista de compras, calendario, recetas, cuadernos (títulos y texto de las páginas), metas, tablas y libros, agrupados por tipo; toca uno para ir directo allí.",
    faq_a_my_day: "Mi Día reúne lo que antes eran Un Vistazo al Día de Hoy y Mi Rutina, en una sola línea de tiempo. Abajo en la pantalla de inicio ves cuánto llevas hecho, qué toca ahora o después (con un ✓ rápido) y, junto al título, un vaso de agua con +1. Tócalo (o deslízalo hacia arriba) para abrir el día entero: arriba lo que no tiene hora, y luego todo por horas – tareas, eventos y reuniones del calendario, los horarios fijos semanales, la rutina de hoy, los pequeños pasos de tus metas y las comidas de New Me – con una línea de ahora. Filtra por Tareas, Rutina o Reuniones y eventos. Un ✓ aquí es el mismo ✓ en todas partes (Mi Rutina, Mis Metas, el calendario) y abre una margarita en el rincón. 'Editar mi rutina' abre Mi Rutina (también está en el menú) y '＋ Añadir para hoy' añade una tarea para hoy. Al tocar el título \"Mi Día\" (o la barrita de arriba) se vuelve a cerrar.",
