    nm_gift_intro: "Los {n} retos, paso a paso. Esto es lo que esperaba:",
    nm_gift_title: "Tu regalo",
    faq_a_new_me_letter_gift: "Al empezar New Me (o más tarde, en Retos) se puede escribir una carta para ti en el futuro. Una vez sellada, no se puede leer ni editar hasta que se abre: en la botella del mar de la habitación secreta, o al completar los 20 retos, donde también te espera un regalo.",
    faq_q_new_me_letter_gift: "¿Qué es la carta del pasado?",
    faq_a_new_me_challenges: "🏆 Retos tiene 20 retos: 10 grandes (como 5 días sin azúcar, una semana sin carbohidratos o perder 4 kg en un mes – déficit calórico, entrenamiento y sin azúcar cada día) y 10 mini – pequeños hábitos durante una semana, como café con canela sin azúcar. Al elegir un reto se pregunta cuándo empezar: hoy, mañana, la semana que viene u otra fecha. Un reto grande y un mini reto pueden ir a la vez. El reto en curso aparece arriba del menú y en Mi Día, con un ✓ para el día. Cada semana de reto trae un día libre (🍕) que no lo rompe, y un día sin marcar cuenta como día libre – se puede marcar hoy y también ayer. Algunos días se marcan solos: un entrenamiento de 20 minutos en Seguimiento de Entrenamientos, o las comidas del menú con ✓. Cada reto tiene una ⓘ con lo que cuenta exactamente (por ejemplo, la lista completa de carbohidratos), en el propio reto y a su lado en Mi Día. Debajo, 🌱 Crecimiento personal tiene 48 pequeños retos de una semana (no cuentan para los 20): consulta «¿Qué es el reto de la semana?».",
    faq_q_new_me_challenges: "¿Cómo funcionan los retos de New Me?",
    nm_letter_too_short: "Unas palabras más 🙂",
    nm_letter_quiz_note: "Opcional – también se puede escribir más tarde, en Retos.",
    nm_letter_write: "✍️ Escribir la carta",
