    nm_ch_completed_label: "retos completados",
    nm_tile_challenges: "Retos",
    faq_a_workout_calories: "Sí. Cada entrenamiento recibe una estimación de las calorías quemadas – según el tipo, la duración y tu último peso (al correr y en bici también según la velocidad, si se indica la distancia). Aparece en la lista de entrenamientos y en el resumen mensual (Quemadas), y se suma al presupuesto de calorías de ese día: en el Registro Diario de Comidas, en Métricas de Calorías y Peso y en el anillo de New Me. Es una estimación, por eso se muestra con ~.",
    faq_q_workout_calories: "¿Los entrenamientos cuentan en mis calorías del día?",
    faq_a_new_me_flexible_menu: "Sí. En el cuestionario y en los ajustes se elige cuántas comidas al día – 2 comidas + un tentempié / 2 comidas + una cena ligera / 2 comidas + un tentempié + una cena ligera – y ➖ en la tarjeta de una comida la quita (quedan al menos 3); «➕ Volver a añadir» la devuelve. En todos los casos las calorías del día no cambian: lo que se quita se reparte entre las demás comidas, y cada comida muestra cuánto se le sumó y qué se le puede añadir. ✏️ Editar en una comida abre su texto: cambia lo que quieras (p. ej. sin pan o con un huevo más) y la IA vuelve a calcular las calorías y la proteína. 🔄 Cambiar ofrece opciones del menú, ⭐ Guardadas y ✨ Escribirla; cada cambio puede ser solo para hoy o desde ahora. Y al final de «Todo el día» está ➕ Añadir comida: escribe lo que se comió fuera del menú y la IA lo calcula y lo suma a hoy (✕ lo borra).",
