    vision_focus_ribbon: "🎯 Meta del mes",
    vision_tagline: "Grandes metas, pequeños pasos.",
    faq_a_app_tour: "El recorrido se abre solo una vez, la primera vez que entras. Empieza con sus partes – toca una para ir directo a ella – y luego muestra todas las partes de la app (la pantalla de inicio, el asistente de IA y cada elemento del menú) y los cinco grupos de Ajustes, cada uno con una breve explicación, y se asoma por dentro a algunos (por ejemplo, un camino de meta de ejemplo, la mochila y Google Calendar). Continuar avanza, Atrás vuelve, Saltar esta parte pasa a la siguiente parte y ✕ cierra el recorrido. Puedes repetirlo cuando quieras desde Ajustes > Ayuda y uso > Recorrido de la app, y seguir donde lo dejaste. Continuar y Atrás están siempre en el mismo lugar, abajo en la pantalla, y en la computadora también funcionan las flechas del teclado.",
    faq_q_app_tour: "¿Cómo vuelvo a ver el recorrido de la app?",
    apptour_done_text: "¿Alguna pregunta? En Ajustes, Ayuda y preguntas frecuentes lo responde todo, y este recorrido siempre está en Ayuda y uso.",
    apptour_done_title: "¡Eso es todo! 🎉",
    apptour_flow_recurring: "Cuotas y órdenes permanentes",
    apptour_flow_weight: "Peso",
    apptour_flow_calories: "Calorías de hoy",
    apptour_flow_calendar: "Calendario",
    apptour_connect_text: "Lo que haces en un lugar actualiza los demás automáticamente:",
    apptour_connect_title: "Todo está conectado",
    apptour_s_support_text: "Ayuda y preguntas frecuentes, contacto, compartir la app – y este recorrido, cuando quieras.",
    apptour_s_account_text: "Premium, contraseña, un informe personal en PDF, sincronización con Google Calendar y eliminación de la cuenta.",
    apptour_s_notifications_text: "Notificaciones de recordatorios y su sonido. '⏰ Todavía no' en un recordatorio funciona como el botón de posponer de una alarma: te avisa de nuevo cada 5 minutos.",
    apptour_s_personalization_text: "País, comidas y snacks por día, cuándo empieza tu mes financiero y qué se muestra en la pantalla de inicio.",
    apptour_s_appearance_text: "Idioma, modo claro u oscuro, temas, fuente, color de texto, accesibilidad y tamaño de la app.",
    apptour_m_style_text: "Este botón cambia el menú a mosaicos grandes – y viceversa. En la pantalla de inicio solo aparece uno de los dos.",
    apptour_m_style_title: "Lista o mosaicos",
    apptour_m_receipts_link: "Exporta una categoría como PDF, o suma todo por años con 🧮.",
    apptour_m_receipts_text: "Guarda facturas y recibos con fotos, para el hogar o el negocio.",
    apptour_m_budget_link: "Cuotas y órdenes permanentes (con importación desde Excel), tus propias categorías y un día de reinicio del presupuesto en Ajustes.",
    apptour_m_budget_text: "Gastos e ingresos por categoría, con un saldo mensual.",
    apptour_m_steps_text: "Tu conteo diario de pasos.",
