    apptour_m_meals_text: "Registra cada comida con calorías y proteína, día a día.",
    apptour_m_recipes_link: "Escanea una receta escrita con 📷 Foto en el Asistente de IA.",
    apptour_m_recipes_text: "Tus recetas por categoría, con fotos, calorías y porciones.",
    apptour_m_goal_link: "Puede seguir tu peso o las tareas completadas automáticamente.",
    apptour_m_goal_text: "Una meta para el mes, con barra de progreso y una recompensa al lograrla.",
    apptour_m_shopping_link: "Añade productos desde Nota Rápida en un segundo.",
    apptour_m_shopping_text: "Tu lista de compras – marca los productos en la tienda.",
    apptour_m_notes_link: "Arrastra una nota a Hoy, Mañana u Otra Fecha para convertirla en tarea; las notas borradas esperan en el archivo 🗑️.",
    apptour_m_notes_text: "Notas e ideas en una sola lista.",
    apptour_m_tables_link: "El Asistente de IA puede diseñar una tabla automáticamente.",
    apptour_m_tables_text: "Tablas personales – regalos, series, listas – con columnas de texto, número, selección, fecha y ✓ (Premium).",
    apptour_m_study_link: "🪄 El Reparto Inteligente, en la tarjeta ✅ Tareas, divide una tarea grande en pasos en tu calendario.",
    apptour_m_study_text: "Tu bolso: un bolsillo para cada parte de la vida – con cuadernos, tablas y tareas dentro.",
    apptour_m_vision_link: "📅 en un hito lo pone en el calendario; los pequeños pasos y las tareas de un reto de días aparecen en Mi Día, y el progreso también puede seguir un número o tu peso.",
    apptour_m_vision_text: "Tus metas como caminos de pequeños pasos – con los pasos de hoy arriba. Echemos un vistazo dentro 👇",
    apptour_m_myweek_link: "Se sincroniza con Google Calendar (en Ajustes).",
    apptour_m_myweek_text: "El calendario mensual, tareas semanales recurrentes con recordatorios y todos tus eventos con fecha. Y una agenda de papel con las reuniones de la semana 🤝.",
    apptour_m_newme_link: "Todo cuenta en el Registro Diario de Comidas y en Mi Día; el peso se comparte con Métricas de Calorías y Peso.",
    apptour_m_newme_text: "Un plan de comidas de 1.300 / 1.500 calorías dentro de un mundo de juego mágico: el menú de hoy con ✓, cambios de tres maneras – del menú, de tus comidas guardadas o escribiéndole a la IA lo que comiste, y calcula las calorías – lista de compras, recordatorios de comidas y un camino de progreso con logros, medidas y fotos. Y además, 🏆 20 retos – con un regalo al final – y un reto de la semana.",
    apptour_ai_table_text: "Describe la tabla que necesitas – la IA diseña sus columnas (Premium).",
    apptour_ai_photo_link: "Se guarda en Mis Recetas.",
    apptour_ai_photo_text: "Fotografía una receta escrita – la IA completa una receta nueva por ti.",
    apptour_ai_schedule_link: "Aparecen en el calendario y en Mi Día.",
    apptour_ai_schedule_text: "Describe tus planes con palabras sencillas, únicos o recurrentes – van directo al calendario.",
    apptour_ai_food_link: "Va directo al Registro Diario de Comidas y al total de hoy.",
    apptour_ai_food_text: "Escribe lo que comiste – las calorías se estiman y se registran por ti.",
    apptour_newme_short_text: "Abre New Me: el menú de hoy está directamente en la pantalla principal.",
    apptour_ai_link: "Un pequeño 1 encima es el recordatorio diario de «lo importante de hoy».",
    apptour_ai_text: "Escribe con palabras sencillas y tu asistente hace el resto: registra calorías, pone planes en tu calendario, lee una receta desde una foto y crea tablas.",
    apptour_quicknote_link: "📝 y 🛒 abren las listas completas; 🍎 registra una comida guardada en el Registro Diario de Comidas.",
    apptour_quicknote_text: "Anota algo rápido – en tus Notas o directamente en la Lista de Compras.",
    apptour_routine_link: "Un hábito puede registrar un entrenamiento en Seguimiento de Entrenamientos automáticamente.",
    apptour_routine_text: "Tu rutina diaria por horas, en pestañas (niños, estudio, trabajo…). Marca ✓ cada día para crear hábitos y rachas; 📅 muestra todo el mes.",
    apptour_premium_text: "Desbloquea el asistente de IA completo, temas, fuentes, Mi bolso y más.",
    apptour_note_text: "Una nota adhesiva para toda la semana. Dentro, el engranaje ⚙ añade una lista de verificación de 1–3 líneas y cambia su color y estilo.",
    apptour_peek_link: "Aquí aparecen las tareas de la IA, del calendario y de Google Calendar y los hitos de tus metas – además de las calorías de hoy 🔥 y tu 🎯 meta del mes.",
    apptour_peek_text: "Todo lo de hoy en un solo lugar: tareas, reuniones, tu rutina y los pequeños pasos en una línea de tiempo. Marca ✓ aquí mismo.",
    apptour_date_text: "Tócala para echar un vistazo rápido al calendario mensual – y añadir algo al instante.",
    apptour_date_title: "La fecha",
