    nm_drink_hot_ph: "☕ Café / té",
    nm_drink_milk_word: "leche",
    nm_drink_milk_ph: "🥛 ¿Leche? ¿Cuánta?",
    table_select_option_delete_confirm: "Esta opción se usa en {count} filas. ¿Eliminarla? Esas celdas quedarán vacías.",
    table_select_option_delete_title: "Eliminar opción",
    faq_a_other_manual_option: "Siempre que eliges de una lista de opciones, también está '✏️ Otro': selecciónala y escribe exactamente lo que necesitas. En una tabla con una columna de selección (por ejemplo 'Parentesco' en una tabla de regalos), toca la celda, elige '✏️ Otro', escribe el valor (por ejemplo 'Sobrino') y toca Añadir: se guarda como una nueva opción de esa columna, así que la próxima vez ya aparece en la lista. La pequeña × junto a cada opción de esa lista elimina la opción de la columna. Al elegir el icono de una tabla hay muchos iconos (incluidas notas adhesivas de colores). Funciona igual en las categorías de comidas guardadas, las categorías de recetas, las categorías de gastos recurrentes (se guarda como una nueva categoría personal) y las categorías de metas en Mis Metas.",
    faq_q_other_manual_option: "La opción que necesito no está en la lista, ¿qué puedo hacer?",
