    finance_category_new_option: "➕ Nueva categoría…",
    menu_switch_to_list: "Cambiar a vista de lista",
    menu_switch_to_tiles: "Cambiar a vista de mosaicos",
    faq_a_receipts_total: "En la pantalla Facturas / Recibos, toca 🧮 'Total de todos los recibos'. Elige desde qué año hasta qué año (por defecto, desde el recibo más antiguo hasta este año), toca Calcular y aparecerá el total de ambas categorías juntas - Gastos del hogar y Gastos de negocio - además de cuántos recibos hay y el total de cada categoría por separado.",
    faq_q_receipts_total: "¿Cómo sumar todos los recibos de un período?",
    receipts_total_empty: "No hay recibos en estos años.",
    receipts_total_invalid: "Introduce un rango de años válido",
    receipts_total_count: "Recibos: {count}",
    receipts_total_calc_btn: "Calcular",
    receipts_total_to_year: "Hasta el año",
    receipts_total_from_year: "Desde el año",
    receipts_total_title: "Total de todos los recibos",
    receipts_total_tile: "Total de todos los recibos",
    faq_a_quick_note_apple: "La 🍎 junto a 📝 y 🛒 en la ventana de notas es un acceso directo para registrar rápidamente una de tus comidas guardadas en el Registro Diario de Comidas de hoy. Está activada por defecto: si no la necesitas, desactívala en Ajustes > Personalización y calendario ('Mostrar el acceso directo 🍎 a comidas guardadas en la ventana de notas') y vuelve a activarla ahí cuando quieras.",
    faq_q_quick_note_apple: "¿Qué es la 🍎 en la ventana de notas y puedo ocultarla?",
    settings_quick_note_apple_label: "Mostrar el acceso directo 🍎 a comidas guardadas en la ventana de notas",
    faq_a_vision_board_today: "En Mis Metas, debajo del camino de una meta (en 'El plan'), toca 📅 junto a un hito y elige una fecha. También puedes activar '🔁 Cada semana hasta completarlo' – así vuelve cada semana el mismo día hasta que lo marques una vez. El hito aparece ese día en Mi Día y en el calendario (y en Google Calendar, si está conectado), y el botón muestra cuándo está programado. Un ✓ en cualquiera de los dos lugares lo marca también en el otro y hace avanzar el camino de la meta. Vuelve a tocar 📅 para cambiar la fecha o quitarlo del calendario. Eliminar del calendario una tarea que no se repite también elimina el hito de la meta; eliminar una semana de un recordatorio semanal quita solo esa semana.",
    faq_q_vision_board_today: "¿Cómo pongo un hito de una meta en el calendario (📅)?",
    vision_milestone_already_today: "Este hito ya está en las tareas de hoy.",
    auth_consent_required: "Para registrarse es necesario aceptar los Términos de uso y la Política de privacidad.",
    auth_consent_privacy: "Política de privacidad",
    auth_consent_terms: "Términos de uso",
    auth_consent_label: "He leído y acepto los {terms} y la {privacy}, y tengo 16 años o más.",
    nm_bonus_sub: "Una lectura breve sobre pesarse, pasarse del objetivo y comer fuera",
    nm_bonus_label: "Bonus",
    nm_shortcut_title: "New Me – mi menú de hoy",
    nm_remove: "Quitar",
    nm_split_line: "Plan {plan} · Bebidas {drinks} · Extras {extra}",
    nm_extras_hint: "Del Registro Diario de Comidas y del añadido rápido: ya se cuenta en el anillo.",
    nm_extras_title: "Hoy, fuera del plan",
    nm_drinks_total: "{n} / ~{kcal} kcal",
    nm_drink_missing: "Introduce el nombre de la bebida y sus calorías",
    nm_drink_more: "+ Otra bebida",
    nm_drink_add: "Añadir",
    nm_drink_name_ph: "Bebida (p. ej., zumo)",
    nm_drinks_hint: "Basta con escribir la bebida: las calorías se calculan automáticamente y el número se puede cambiar.",
    nm_slot_drinks: "Bebidas",
    faq_a_new_me_tracking: "Toca la siguiente misión, arriba en New Me, y luego ✓ Comí para marcar que la siguiente comida ya se comió: el menú completo con ✓ en cada comida está en Todo el día, en el lateral, y las comidas de hoy también aparecen en Mi Día en la pantalla de inicio; al tocar una allí (o pasar el ratón por encima) se ve exactamente qué comer, con ✓ y Cambiar. Todo se sincroniza con el Registro Diario de Comidas: las comidas del plan, las bebidas y lo que añadas en otro lugar (por ejemplo, un café desde el añadido rápido) se cuentan juntos en New Me y en Mi Día; no se sobrescribe nada de lo que ya escribiste, y quitar un ✓ quita solo la parte de New Me. Cuando todas las comidas de hoy están marcadas, hay una pequeña celebración. En «Bebidas» se registran las bebidas del día: todas juntas hasta ~150 kcal, es decir, unas 3 bebidas de hasta ~50 kcal cada una. Basta con escribir el nombre de la bebida y las calorías se rellenan automáticamente con IA. Las dos filas de café/té también tienen un campo «¿Leche? ¿Cuánta?» (por ejemplo «un poco» o «50 ml»), y el cálculo se actualiza; el número se puede cambiar antes de añadir y también después. Una bebida con nombre y calorías se guarda automáticamente en cuanto pasas a otra cosa; tocar Añadir es opcional. Toca ☆ junto a una bebida para guardarla como bebida habitual: las bebidas habituales aparecen como botones arriba de la tarjeta de Bebidas, y un toque las añade al día. ⭐ guarda una comida como comida guardada. «Tabla diaria» muestra lo que comiste con calorías y proteína. El pequeño 💎 junto al modo enfoque, arriba en la pantalla de inicio, lo abre directamente. Los valores de calorías y proteína son estimaciones de IA y pueden contener errores. ¿No te lo comiste todo? Debajo de una comida marcada, «¿No te lo comiste todo?» quita un cuarto, la mitad o tres cuartos de la porción – o lo que escribas, calculado – y las calorías del día se actualizan.",
    faq_q_new_me_tracking: "¿Cómo funcionan el ✓, los cambios y las calorías en New Me?",
    faq_a_new_me_what: "New Me es un programa de menú diario independiente con dos planes listos (1.300 o 1.500 calorías), formados por 2 comidas principales y 2 tentempiés, con 3 opciones para cada uno. Incluye todo Premium. Precio: $11.99 al mes (cancelable cuando quieras) o $99.99 una sola vez, de por vida. Se abre desde 💎 New Me en el menú. Antes de empezar hay un cuestionario corto que comienza con un aviso médico que hay que aceptar. El programa es solo información general y no sustituye a un médico ni a un dietista clínico.",
    faq_q_new_me_what: "¿Qué es New Me y cómo lo consigo?",
