    faq_q_daily_focus_prompt: "¿Qué es el recordatorio que me pregunta qué es lo más importante para hacer hoy?", faq_a_daily_focus_prompt: "Es un recordatorio diario Premium: una vez al día aparece un pequeño distintivo «1» en el icono del asistente de IA. Toca el distintivo para abrir una burbuja que pregunta qué es lo más importante para ti hoy, con 5 sugerencias listas ahí mismo (cambian cada día y rotan entre temas distintos durante todo un año, para que no se repitan) más 'Otro' para escribir la tuya; puedes elegir más de una. Toca Añadir y lo que elegiste aparece como pequeñas etiquetas de recordatorio arriba de 'Mi Día' (no son tareas para marcar). Si lo cierras con ✕ o tocas fuera, el distintivo solo se atenúa por el resto del día en lugar de desaparecer. Viene activado por defecto, pero puedes desactivarlo en Ajustes > Personalización y calendario. ¿Hoy no es el día? Toca '🌙 Hoy no': la insignia desaparece hasta mañana, cuando la pregunta vuelve como siempre. Una de las sugerencias sale de tu propia vida – el siguiente paso de tu meta del mes o la lectura de hoy. Cada día empieza de nuevo.",
